def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_color = grid[sep_rows[0]][0]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]

    def parts(n, separators):
        result, start = [], 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < n:
            result.append((start, n))
        return result

    rp, cp = parts(h, sep_rows), parts(w, sep_cols)
    cells = [grid[r][c] for r0, r1 in rp for c0, c1 in cp
             for r in range(r0, r1) for c in range(c0, c1)]
    from collections import Counter
    background = Counter(cells).most_common(1)[0][0]
    marker = next(v for v in set(cells) if v != background and v != sep_color)

    out = [[background for _ in cp] for _ in rp]
    for i, (r0, r1) in enumerate(rp):
        for j, (c0, c1) in enumerate(cp):
            count = sum(grid[r][c] == marker
                        for r in range(r0, r1) for c in range(c0, c1))
            if count == 2:
                out[i][j] = 1
    return out
